  bindAdminFilters(renderInterventions);$('#newT2').onclick=()=>openT2Modal();app.querySelectorAll('[data-view-int]').forEach(b=>b.onclick=()=>viewIntervention(b.dataset.viewInt));app.querySelectorAll('[data-edit-int]').forEach(b=>b.onclick=()=>openT2Modal(b.dataset.editInt));app.querySelectorAll('[data-delete-int]').forEach(b=>b.onclick=()=>deleteIntervention(b.dataset.deleteInt));app.querySelectorAll('[data-approve]').forEach(b=>b.onclick=()=>approveIntervention(b.dataset.approve,true));app.querySelectorAll('[data-reject]').forEach(b=>b.onclick=()=>approveIntervention(b.dataset.reject,false));
