function viewIntervention(id){const i=state.data.interventions.find(x=>x.id===id);if(!i)return;const e=employeeById(i.colaborador_id),p=projectById(i.proyecto_id);openModal(`<h2>Detalle de intervención</h2><div class="detail-list"><div class="detail-row"><b>Fecha</b><span>${esc(i.fecha_intervencion)}</span><span></span><span></span></div><div class="detail-row"><b>Colaborador</b><span>${esc(fullName(e))}</span><span></span><span></span></div><div class="detail-row"><b>Proyecto</b><span>${esc(p?.codigo_proyecto||'')}</span><span></span><span></span></div><div class="detail-row"><b>Inicio - fin</b><span>${esc(timeRange(i))}</span><span></span><span></span></div><div class="detail-row"><b>Ticket</b><span>${esc(i.ticket||'—')}</span><span></span><span></span></div><div class="detail-row"><b>Actividad</b><span>${esc(i.actividad)}</span><span></span><span></span></div><div class="detail-row"><b>Estado</b><span>${esc(i.estado)}</span><span></span><span></span></div></div>`)}
async function approveIntervention(id,yes){const i=state.data.interventions.find(x=>x.id===id);const r=rateRecord('T2',i.fecha_intervencion);const patch=yes?{estado:'APROBADO',aprobado_por:state.session.user.id,aprobado_at:new Date().toISOString(),tarifa_id:r?.id||null,tarifa_aplicada:Number(r?.valor||0),valor_calculado:Number(r?.valor||0)}:{estado:'RECHAZADO',aprobado_por:state.session.user.id,aprobado_at:new Date().toISOString()};const {error}=await db.from('intervenciones').update(patch).eq('id',id);if(error)return notify(normalizeError(error),'error');notify(yes?'Intervención aprobada':'Intervención rechazada');refreshData()}
async function deleteIntervention(id){if(!isAdmin())return;if(!confirm('¿Eliminar esta intervención? Esta acción queda registrada en auditoría.'))return;const {error}=await db.from('intervenciones').delete().eq('id',id);if(error)return notify(normalizeError(error),'error');notify('Intervención eliminada');refreshData()}
function openT2Modal(id=null){
  const current=id?state.data.interventions.find(x=>x.id===id):null;if(current&&!isAdmin()&&!canEditOwnIntervention(current))return notify('Esta intervención ya no puede editarse.','error');
  const candidateGuards=state.data.planning.filter(g=>g.estado==='ASIGNADA'&&(isAdmin()?true:g.colaborador_id===state.currentEmployeeId)).sort((a,b)=>b.fecha_guardia.localeCompare(a.fecha_guardia));
  const selectedEmployee=current?.colaborador_id||(isAdmin()?state.data.employees.find(e=>e.estado==='ACTIVO')?.id:state.currentEmployeeId);const employeeOptions=isAdmin()?state.data.employees.filter(e=>e.estado==='ACTIVO'||e.id===selectedEmployee).map(e=>`<option value="${e.id}" ${e.id===selectedEmployee?'selected':''}>${esc(e.codigo_empleado)} · ${esc(fullName(e))}</option>`).join(''):'';
  openModal(`<h2>${current?'Editar':'Registrar'} intervención T2</h2><p class="muted">El sistema exige una guardia T1 existente.</p><form id="t2Form"><div class="form-grid">${isAdmin()?`<label>Colaborador<select id="t2Employee">${employeeOptions}</select></label>`:''}<label>Guardia<select id="t2Guard"></select></label><label>Fecha intervención<input id="t2Date" type="date" required value="${esc(current?.fecha_intervencion||'')}"></label><label>Ticket / incidente<input id="t2Ticket" placeholder="INC... (opcional)" value="${esc(current?.ticket||'')}"></label><label>Inicio<input id="t2Start" type="datetime-local" required value="${esc(toLocalInput(current?.inicio))}"></label><label>Fin<input id="t2End" type="datetime-local" required value="${esc(toLocalInput(current?.fin))}"></label><label class="full">Actividad<textarea id="t2Activity" required placeholder="Describe brevemente la intervención remota">${esc(current?.actividad||'')}</textarea></label></div><div id="t2Error" class="alert error hidden"></div><div class="form-actions"><button type="button" class="secondary" onclick="closeModal()">Cancelar</button><button class="primary" type="submit">${current?'Guardar cambios':'Guardar y enviar'}</button></div></form>`);
  const fill=(preserve=true)=>{const eid=isAdmin()?$('#t2Employee').value:state.currentEmployeeId;const gs=candidateGuards.filter(g=>g.colaborador_id===eid);$('#t2Guard').innerHTML=gs.map(g=>`<option value="${g.id}" ${current?.guardia_id===g.id?'selected':''} data-date="${g.fecha_guardia}" data-project="${g.proyecto_id}">${g.fecha_guardia} · ${esc(projectById(g.proyecto_id)?.codigo_proyecto||'')}</option>`).join('');if(!preserve&&gs[0])setT2Date(gs[0].fecha_guardia)};
  const setT2Date=d=>{$('#t2Date').value=d;$('#t2Start').value=d+'T18:00';$('#t2End').value=d+'T19:00'};
  if(isAdmin())$('#t2Employee').onchange=()=>fill(false);fill(true);if(!current){const o=$('#t2Guard').selectedOptions[0];if(o)setT2Date(o.dataset.date)}$('#t2Guard').onchange=e=>{const o=e.target.selectedOptions[0];if(o)setT2Date(o.dataset.date)};$('#t2Form').onsubmit=e=>saveT2(e,id);
}
async function saveT2(e,id=null){e.preventDefault();const guard=state.data.planning.find(g=>g.id===$('#t2Guard').value);if(!guard)return showT2Error('Selecciona una guardia T1 válida.');const start=new Date($('#t2Start').value),end=new Date($('#t2End').value);const hours=(end-start)/3600000;if(!(hours>0))return showT2Error('La hora fin debe ser posterior a la hora inicio.');const date=$('#t2Date').value,r=rateRecord('T2',date),old=id?state.data.interventions.find(x=>x.id===id):null;const payload={guardia_id:guard.id,colaborador_id:guard.colaborador_id,proyecto_id:guard.proyecto_id,fecha_intervencion:date,inicio:start.toISOString(),fin:end.toISOString(),horas:Math.round(hours*100)/100,ticket:$('#t2Ticket').value.trim()||null,actividad:$('#t2Activity').value.trim(),estado:isAdmin()&&old?old.estado:'PENDIENTE',tarifa_id:r?.id||old?.tarifa_id||null,tarifa_aplicada:Number(r?.valor??old?.tarifa_aplicada??0),valor_calculado:Number(r?.valor??old?.valor_calculado??0),origen:old?.origen||'PORTAL',creado_por:old?.creado_por||state.session.user.id};if(!isAdmin()&&old){payload.aprobado_por=null;payload.aprobado_at=null}let error;if(id)({error}=await db.from('intervenciones').update(payload).eq('id',id));else({error}=await db.from('intervenciones').insert(payload));if(error)return showT2Error(normalizeError(error));closeModal();notify(id?'Intervención actualizada':'Intervención registrada');refreshData()}
function showT2Error(msg){$('#t2Error').textContent=msg;$('#t2Error').classList.remove('hidden')}


function renderEmployees(){setHeader('Colaboradores','CRUD, estado y asignación a proyectos');app.innerHTML=`<div class="card section"><div class="section-head"><div><h2>Maestro de colaboradores</h2><p class="muted">Los inactivos conservan su histórico. Eliminar físicamente solo es posible si no existen registros relacionados.</p></div><button class="primary" id="newEmployee">Nuevo colaborador</button></div><div class="toolbar" style="margin-bottom:12px"><input id="empSearch" placeholder="Buscar por código, nombre o correo"><select id="empStatusFilter"><option value="all">Todos los estados</option><option value="ACTIVO">Activos</option><option value="INACTIVO">Inactivos</option></select></div><div class="table-wrap"><table class="table"><thead><tr><th>Código</th><th>Colaborador</th><th>Dominio</th><th>Proyecto(s)</th><th>Correo</th><th>Estado</th><th>Acciones</th></tr></thead><tbody id="employeesBody"></tbody></table></div></div>`;const draw=()=>{const term=$('#empSearch').value.toLowerCase(),st=$('#empStatusFilter').value;const list=state.data.employees.filter(e=>(st==='all'||e.estado===st)&&(!term||[e.codigo_empleado,fullName(e),e.correo].join(' ').toLowerCase().includes(term)));$('#employeesBody').innerHTML=list.map(e=>{const ps=currentAssignments(e.id).map(a=>projectById(a.proyecto_id)?.codigo_proyecto).filter(Boolean).join(', ');return `<tr><td>${esc(e.codigo_empleado)}</td><td><b>${esc(fullName(e))}</b><div class="muted">${esc(e.cedula||'')}</div></td><td>${esc(domainName(e))}</td><td>${esc(ps||'—')}</td><td>${esc(e.correo||'—')}</td><td><span class="pill ${e.estado==='ACTIVO'?'active':'inactive'}">${e.estado}</span></td><td><div class="action-group"><button class="secondary" data-edit-emp="${e.id}">Editar</button><button class="switch ${e.estado==='ACTIVO'?'on':''}" data-toggle-emp="${e.id}" title="Activar/desactivar"></button><button class="danger" data-delete-emp="${e.id}">Eliminar</button></div></td></tr>`}).join('')};draw();$('#empSearch').oninput=draw;$('#empStatusFilter').onchange=draw;$('#newEmployee').onclick=()=>openEmployeeModal();$('#employeesBody').onclick=e=>{const ed=e.target.closest('[data-edit-emp]'),tg=e.target.closest('[data-toggle-emp]'),del=e.target.closest('[data-delete-emp]');if(ed)openEmployeeModal(ed.dataset.editEmp);if(tg)toggleEmployee(tg.dataset.toggleEmp);if(del)deleteEmployee(del.dataset.deleteEmp)}}
async function toggleEmployee(id){const e=employeeById(id),next=e.estado==='ACTIVO'?'INACTIVO':'ACTIVO';if(!confirm(`¿Cambiar a ${next} a ${fullName(e)}?`))return;const {error}=await db.from('colaboradores').update({estado:next}).eq('id',id);if(error)return notify(normalizeError(error),'error');await db.from('perfiles_usuario').update({estado:next}).eq('colaborador_id',id);notify(`Colaborador ${next.toLowerCase()}`);refreshData()}
async function deleteEmployee(id){const e=employeeById(id);if(!confirm(`¿Eliminar a ${fullName(e)}? Si tiene histórico, se desactivará en lugar de borrarse.`))return;const {error}=await db.from('colaboradores').delete().eq('id',id);if(error){const {error:soft}=await db.from('colaboradores').update({estado:'INACTIVO'}).eq('id',id);if(soft)return notify(normalizeError(soft),'error');notify('El colaborador tiene histórico: se marcó INACTIVO.')}else notify('Colaborador eliminado');refreshData()}
function openEmployeeModal(id=null){const e=id?employeeById(id):null,selected=new Set(id?currentAssignments(id).map(a=>a.proyecto_id):[]);openModal(`<h2>${e?'Editar':'Nuevo'} colaborador</h2><form id="employeeForm"><div class="form-grid"><label>Código empleado<input id="empCode" required value="${esc(e?.codigo_empleado||'')}"></label><label>Estado<select id="empStatus"><option value="ACTIVO" ${e?.estado!=='INACTIVO'?'selected':''}>ACTIVO</option><option value="INACTIVO" ${e?.estado==='INACTIVO'?'selected':''}>INACTIVO</option></select></label><label>Nombres<input id="empNames" required value="${esc(e?.nombres||'')}"></label><label>Apellidos<input id="empLast" required value="${esc(e?.apellidos||'')}"></label><label>Cédula<input id="empCedula" value="${esc(e?.cedula||'')}"></label><label>Correo<input id="empEmail" type="email" value="${esc(e?.correo||'')}"></label><label>Usuario NTT<input id="empUser" value="${esc(e?.usuario_ntt||'')}"></label><label>Teléfono<input id="empPhone" value="${esc(e?.telefono||'')}"></label><label>Dominio<select id="empDomain"><option value="">Sin dominio</option>${state.data.domains.map(d=>`<option value="${d.id}" ${e?.dominio_id===d.id?'selected':''}>${esc(d.nombre)}</option>`).join('')}</select></label><label>Sociedad<input id="empSociedad" value="${esc(e?.sociedad||'NECU')}"></label><label class="full">Proyecto(s)<select id="empProjects" multiple size="6">${state.data.projects.filter(p=>p.estado==='ACTIVO').map(p=>`<option value="${p.id}" ${selected.has(p.id)?'selected':''}>${esc(p.codigo_proyecto)} · ${esc(p.nombre)}</option>`).join('')}</select></label></div><div id="empError" class="alert error hidden"></div><div class="form-actions"><button type="button" class="secondary" onclick="closeModal()">Cancelar</button><button class="primary" type="submit">Guardar</button></div></form>`);$('#employeeForm').onsubmit=ev=>saveEmployee(ev,id)}
async function saveEmployee(ev,id){ev.preventDefault();const payload={codigo_empleado:$('#empCode').value.trim(),nombres:$('#empNames').value.trim(),apellidos:$('#empLast').value.trim(),cedula:$('#empCedula').value.trim()||null,correo:$('#empEmail').value.trim()||null,usuario_ntt:$('#empUser').value.trim()||null,telefono:$('#empPhone').value.trim()||null,dominio_id:$('#empDomain').value||null,sociedad:$('#empSociedad').value.trim()||'NECU',estado:$('#empStatus').value};let eid=id;if(id){const {error}=await db.from('colaboradores').update(payload).eq('id',id);if(error)return empError(normalizeError(error))}else{const {data,error}=await db.from('colaboradores').insert(payload).select('id').single();if(error)return empError(normalizeError(error));eid=data.id}const selected=[...$('#empProjects').selectedOptions].map(o=>o.value);const existing=state.data.assignments.filter(a=>a.colaborador_id===eid&&a.estado==='ACTIVO');for(const a of existing.filter(a=>!selected.includes(a.proyecto_id)))await db.from('colaborador_proyecto').update({estado:'INACTIVO',fecha_fin:isoToday()}).eq('id',a.id);for(const pid of selected.filter(pid=>!existing.some(a=>a.proyecto_id===pid)))await db.from('colaborador_proyecto').insert({colaborador_id:eid,proyecto_id:pid,es_principal:selected[0]===pid,estado:'ACTIVO'});closeModal();notify('Colaborador guardado');refreshData()}
function empError(msg){$('#empError').textContent=msg;$('#empError').classList.remove('hidden')}


function renderProjects(){setHeader('Proyectos','CRUD completo de proyectos');app.innerHTML=`<div class="card section"><div class="section-head"><h2>Proyectos</h2><button class="primary" id="newProject">Nuevo proyecto</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Código</th><th>Proyecto</th><th>Project Manager</th><th>Responsable</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${state.data.projects.map(p=>`<tr><td>${esc(p.codigo_proyecto)}</td><td>${esc(p.nombre)}</td><td>${esc(p.project_manager||'—')}</td><td>${esc(p.responsable_directo||'—')}</td><td><span class="pill ${p.estado==='ACTIVO'?'active':'inactive'}">${p.estado}</span></td><td><div class="action-group"><button class="secondary" data-edit-project="${p.id}">Editar</button><button class="danger" data-delete-project="${p.id}">Eliminar</button></div></td></tr>`).join('')}</tbody></table></div></div>`;$('#newProject').onclick=()=>openProjectModal();app.querySelectorAll('[data-edit-project]').forEach(b=>b.onclick=()=>openProjectModal(b.dataset.editProject));app.querySelectorAll('[data-delete-project]').forEach(b=>b.onclick=()=>deleteProject(b.dataset.deleteProject))}
function openProjectModal(id=null){const p=id?projectById(id):null;openModal(`<h2>${p?'Editar':'Nuevo'} proyecto</h2><form id="projectForm"><div class="form-grid"><label>Código<input id="pCode" required value="${esc(p?.codigo_proyecto||'')}"></label><label>Nombre<input id="pName" required value="${esc(p?.nombre||'')}"></label><label>Project Manager<input id="pManager" value="${esc(p?.project_manager||'')}"></label><label>Responsable directo<input id="pResponsible" value="${esc(p?.responsable_directo||'')}"></label><label>Cliente<input id="pClient" value="${esc(p?.cliente||'')}"></label><label>Estado<select id="pStatus"><option value="ACTIVO" ${p?.estado!=='INACTIVO'?'selected':''}>ACTIVO</option><option value="INACTIVO" ${p?.estado==='INACTIVO'?'selected':''}>INACTIVO</option></select></label></div><div class="form-actions"><button type="button" class="secondary" onclick="closeModal()">Cancelar</button><button class="primary">Guardar</button></div></form>`);$('#projectForm').onsubmit=async e=>{e.preventDefault();const payload={codigo_proyecto:$('#pCode').value.trim(),nombre:$('#pName').value.trim(),project_manager:$('#pManager').value.trim()||null,responsable_directo:$('#pResponsible').value.trim()||null,cliente:$('#pClient').value.trim()||null,estado:$('#pStatus').value};let error;if(id)({error}=await db.from('proyectos').update(payload).eq('id',id));else({error}=await db.from('proyectos').insert(payload));if(error)return notify(normalizeError(error),'error');closeModal();notify('Proyecto guardado');refreshData()}}
async function deleteProject(id){const p=projectById(id);if(!confirm(`¿Eliminar el proyecto ${p?.codigo_proyecto}? Si tiene histórico, se desactivará.`))return;const {error}=await db.from('proyectos').delete().eq('id',id);if(error){const {error:soft}=await db.from('proyectos').update({estado:'INACTIVO'}).eq('id',id);if(soft)return notify(normalizeError(soft),'error');notify('El proyecto tiene histórico: se marcó INACTIVO.')}else notify('Proyecto eliminado');refreshData()}
function renderRates(){setHeader('Tarifas','CRUD e histórico de valores T1/T2');app.innerHTML=`<div class="card section"><div class="section-head"><div><h2>Tarifas</h2><p class="muted">Las tarifas se mantienen en base con vigencias. Si una tarifa ya fue usada, conviene desactivarla en lugar de borrarla.</p></div><button class="primary" id="newRate">Nueva tarifa</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Tipo</th><th>Día</th><th>Valor</th><th>Moneda</th><th>Desde</th><th>Hasta</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${state.data.rates.map(r=>`<tr><td><span class="pill ${r.tipo_guardia.toLowerCase()}">${r.tipo_guardia}</span></td><td>${r.tipo_dia}</td><td>${fmtMoney(r.valor)}</td><td>${r.moneda}</td><td>${r.fecha_inicio_vigencia}</td><td>${r.fecha_fin_vigencia||'—'}</td><td><span class="pill ${r.estado==='ACTIVO'?'active':'inactive'}">${r.estado}</span></td><td><div class="action-group"><button class="secondary" data-edit-rate="${r.id}">Editar</button><button class="danger" data-delete-rate="${r.id}">Eliminar</button></div></td></tr>`).join('')}</tbody></table></div></div>`;$('#newRate').onclick=()=>openRateModal();app.querySelectorAll('[data-edit-rate]').forEach(b=>b.onclick=()=>openRateModal(b.dataset.editRate));app.querySelectorAll('[data-delete-rate]').forEach(b=>b.onclick=()=>deleteRate(b.dataset.deleteRate))}
function openRateModal(id=null){const r=id?state.data.rates.find(x=>x.id===id):null;openModal(`<h2>${r?'Editar':'Nueva'} tarifa</h2><form id="rateForm"><div class="form-grid"><label>Tipo<select id="rType"><option value="T1" ${r?.tipo_guardia!=='T2'?'selected':''}>T1</option><option value="T2" ${r?.tipo_guardia==='T2'?'selected':''}>T2</option></select></label><label>Tipo de día<select id="rDay">${['LABORABLE','FDS','NAVIDAD','AN','FP'].map(x=>`<option value="${x}" ${r?.tipo_dia===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Valor<input id="rValue" type="number" min="0" step="0.01" required value="${esc(r?.valor??'')}"></label><label>Moneda<input id="rCurrency" required value="${esc(r?.moneda||'USD')}"></label><label>País<input id="rCountry" required value="${esc(r?.pais||'Ecuador')}"></label><label>Desde<input id="rFrom" type="date" required value="${esc(r?.fecha_inicio_vigencia||isoToday())}"></label><label>Hasta<input id="rTo" type="date" value="${esc(r?.fecha_fin_vigencia||'')}"></label><label>Estado<select id="rStatus"><option value="ACTIVO" ${r?.estado!=='INACTIVO'?'selected':''}>ACTIVO</option><option value="INACTIVO" ${r?.estado==='INACTIVO'?'selected':''}>INACTIVO</option></select></label></div><div class="form-actions"><button type="button" class="secondary" onclick="closeModal()">Cancelar</button><button class="primary">Guardar</button></div></form>`);$('#rateForm').onsubmit=async e=>{e.preventDefault();const payload={tipo_guardia:$('#rType').value,tipo_dia:$('#rDay').value,valor:Number($('#rValue').value),moneda:$('#rCurrency').value.trim(),pais:$('#rCountry').value.trim(),fecha_inicio_vigencia:$('#rFrom').value,fecha_fin_vigencia:$('#rTo').value||null,estado:$('#rStatus').value};let error;if(id)({error}=await db.from('tarifas_guardia').update(payload).eq('id',id));else({error}=await db.from('tarifas_guardia').insert(payload));if(error)return notify(normalizeError(error),'error');closeModal();notify('Tarifa guardada');refreshData()}}
async function deleteRate(id){if(!confirm('¿Eliminar esta tarifa? Si está utilizada por intervenciones, se desactivará.'))return;const {error}=await db.from('tarifas_guardia').delete().eq('id',id);if(error){const {error:soft}=await db.from('tarifas_guardia').update({estado:'INACTIVO'}).eq('id',id);if(soft)return notify(normalizeError(soft),'error');notify('La tarifa tiene histórico: se marcó INACTIVA.')}else notify('Tarifa eliminada');refreshData()}


function renderReports(){setHeader('Reportes','Horas, valores individuales y total del mes');const rows=aggregateByEmployee(),total=rows.reduce((a,b)=>a+b.total,0),hours=rows.reduce((a,b)=>a+b.hours,0);app.innerHTML=`${adminFilterBar()}<div class="summary-bar"><div><span class="muted">Horas T2</span><br><strong>${fmtHours(hours)}</strong></div><div><span class="muted">Total estimado</span><br><strong>${fmtMoney(total)}</strong></div><div><button class="primary" id="exportXlsx">Descargar Excel</button></div></div><div class="card section"><div class="section-head"><h2>Resumen por colaborador</h2></div>${summaryTable(rows)}</div>`;bindAdminFilters(renderReports);$('#exportXlsx').onclick=exportExcel;app.querySelectorAll('[data-detail]').forEach(x=>x.onclick=()=>showEmployeeDetail(x.dataset.detail))}
function exportExcel(){
  const summary=computeSummary();const grouped=[];for(const r of summary){const e=employeeById(r.employeeId),p=projectById(r.projectId);const groups=new Map();for(const d of r.details){const k=d.tipo+'|'+dayType(d.fecha)+'|'+d.valor;if(!groups.has(k))groups.set(k,{tipo:d.tipo,dia:dayType(d.fecha),valor:d.valor,dates:[],hours:0});const g=groups.get(k);g.dates.push(d.fecha);g.hours+=Number(d.horas||0)}for(const g of groups.values())grouped.push({'Código empleado':e?.codigo_empleado,'Empleado':fullName(e),'Sociedad':e?.sociedad||'','Código proyecto':p?.codigo_proyecto||'','Proyecto':p?.nombre||'','Día':g.dia,'Tipo de Guardia':g.tipo,'Importe Unitario':g.valor,'Número de Días/Intervenciones':g.dates.length,'Total':g.valor*g.dates.length,'Horas T2':g.tipo==='T2'?g.hours:'','Detalle de Días':g.dates.join(', ')})}
  const detail=monthInterventions().map(i=>{const e=employeeById(i.colaborador_id),p=projectById(i.proyecto_id);return {'Código empleado':e?.codigo_empleado,'Empleado':fullName(e),'Proyecto':p?.codigo_proyecto,'Fecha':i.fecha_intervencion,'Inicio':i.inicio||'','Fin':i.fin||'','Horas':Number(i.horas),'Ticket':i.ticket||'','Actividad':i.actividad,'Estado':i.estado,'Tarifa':Number(i.tarifa_aplicada??rate('T2',i.fecha_intervencion))}});
  const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(grouped),'Resumen pago');XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(detail),'Detalle horas');const guards=monthPlanning().map(g=>{const e=employeeById(g.colaborador_id),p=projectById(g.proyecto_id);return {'Código empleado':e?.codigo_empleado,'Empleado':fullName(e),'Proyecto':p?.codigo_proyecto,'Fecha guardia':g.fecha_guardia,'Tipo día':dayType(g.fecha_guardia),'Tarifa T1':rate('T1',g.fecha_guardia)} });XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(guards),'Detalle T1');XLSX.writeFile(wb,`standby_${state.month}.xlsx`)
}
function showEmployeeDetail(eid){const e=employeeById(eid),rows=aggregateByEmployee().find(x=>x.employeeId===eid);if(!rows)return;const d=rows.details.sort((a,b)=>a.fecha.localeCompare(b.fecha));openModal(`<h2>${esc(fullName(e))}</h2><p class="muted">${esc(e.codigo_empleado)} · ${esc(domainName(e))}</p><div class="summary-bar"><div>T1<br><strong>${rows.t1}</strong></div><div>T2<br><strong>${rows.t2}</strong></div><div>Horas<br><strong>${fmtHours(rows.hours)}</strong></div><div>Total<br><strong>${fmtMoney(rows.total)}</strong></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Fecha</th><th>Tipo</th><th>Día</th><th>Horas</th><th>Tarifa</th><th>Proyecto</th></tr></thead><tbody>${d.map(r=>`<tr><td>${r.fecha}</td><td><span class="pill ${r.tipo.toLowerCase()}">${r.tipo}</span></td><td>${dayType(r.fecha)}</td><td>${r.tipo==='T2'?fmtHours(r.horas):'—'}</td><td>${fmtMoney(r.valor)}</td><td>${esc(projectById(r.projectId)?.codigo_proyecto||'')}</td></tr>`).join('')}</tbody></table></div>`)}

function renderCollab(){
  setHeader('Mi standby','Consulta tus días de guardia e intervenciones');const eid=state.currentEmployeeId,e=employeeById(eid);if(!e){app.innerHTML='<div class="card section"><h2>Perfil sin colaborador vinculado</h2><p>Solicita al administrador que vincule tu correo con un colaborador.</p></div>';return}
  state.filters={person:'all',domain:'all',project:'all'};const guards=state.data.planning.filter(g=>g.estado==='ASIGNADA'&&g.colaborador_id===eid&&g.fecha_guardia.startsWith(state.month));const ints=state.data.interventions.filter(i=>i.colaborador_id===eid&&i.fecha_intervencion.startsWith(state.month)&&i.estado!=='RECHAZADO');const byDay=new Set(ints.map(i=>i.fecha_intervencion));const t2=byDay.size,hours=ints.reduce((a,b)=>a+Number(b.horas||0),0),t1Total=guards.reduce((a,g)=>a+rate('T1',g.fecha_guardia),0);let t2Total=0;for(const d of byDay)t2Total+=rate('T2',d);const total=t1Total+t2Total;
  app.innerHTML=`<div class="filterbar"><label>Mes<input id="collabMonth" type="month" value="${state.month}"></label></div><div class="grid-kpi">${kpi('Guardias T1',guards.length,'Días de standby asignados')}${kpi('Días con T2',t2,'Intervenciones válidas')}${kpi('Horas T2',fmtHours(hours),'Horas registradas')}${kpi('Estimado',fmtMoney(total),'Sujeto a aprobación')}</div><div class="content-grid"><div class="card section"><div class="section-head"><div><h2>Mi calendario de standby</h2><p class="muted">Los días marcados con “G” son tus días de guardia.</p></div><div class="action-group"><button class="secondary" id="collabSeeT2">Mis intervenciones</button><button class="primary" id="collabNewT2">Registrar intervención</button></div></div>${collabCalendar(guards)}</div><div class="card section"><h2>Mis días de standby</h2><div class="table-wrap"><table class="table"><thead><tr><th>Fecha</th><th>Proyecto</th><th>Tipo día</th><th>Horario</th></tr></thead><tbody>${guards.sort((a,b)=>a.fecha_guardia.localeCompare(b.fecha_guardia)).map(g=>`<tr><td><b>${g.fecha_guardia}</b></td><td>${esc(projectById(g.proyecto_id)?.codigo_proyecto||'')}</td><td>${dayType(g.fecha_guardia)}</td><td>${dayType(g.fecha_guardia)==='FDS'?'00:00–23:59':'18:00–08:59'}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No tienes guardias en este mes</td></tr>'}</tbody></table></div></div></div><div class="card section"><div class="section-head"><h2>Intervenciones recientes</h2><button class="secondary" id="collabManageT2">Ver / editar</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Fecha</th><th>Inicio - fin</th><th>Ticket</th><th>Actividad</th><th>Estado</th></tr></thead><tbody>${ints.sort((a,b)=>b.fecha_intervencion.localeCompare(a.fecha_intervencion)).slice(0,10).map(i=>`<tr><td>${i.fecha_intervencion}</td><td>${esc(timeRange(i))}</td><td>${esc(i.ticket||'—')}</td><td>${esc(i.actividad)}</td><td><span class="pill ${i.estado==='APROBADO'?'approved':i.estado==='RECHAZADO'?'rejected':'pending'}">${i.estado}</span></td></tr>`).join('')||'<tr><td colspan="5" class="empty">Sin intervenciones</td></tr>'}</tbody></table></div></div>`;
  $('#collabMonth').onchange=e=>{state.month=e.target.value;renderCollab()};$('#collabNewT2').onclick=()=>openT2Modal();$('#collabSeeT2').onclick=$('#collabManageT2').onclick=()=>{state.view='intervenciones';render()};
}

function collabCalendar(guards){const set=new Set(guards.map(g=>g.fecha_guardia)),[y,m]=state.month.split('-').map(Number),first=new Date(y,m-1,1).getDay(),n=daysInMonth(state.month);let html='<div class="month-calendar">'+['Dom','Lun','Mar','Mié','Jue','Vie','Sáb'].map(x=>`<div class="dow">${x}</div>`).join('');for(let i=0;i<first;i++)html+='<div class="calendar-day off"></div>';for(let d=1;d<=n;d++){const f=`${state.month}-${String(d).padStart(2,'0')}`,on=set.has(f);html+=`<div class="calendar-day ${dayType(f)==='FDS'?'weekend':''} ${on?'guard':''}"><span class="num">${d}</span>${on?'<span class="tag">G · Standby</span>':''}</div>`}return html+'</div>'}

function openModal(html){$('#modalContent').innerHTML=html;$('#modal').classList.remove('hidden')}
function closeModal(){$('#modal').classList.add('hidden')}
window.closeModal=closeModal;
init();
